sys_variable_value.value:
(function execute(inputs, outputs) {
    var tr = inputs.trigger_record;
    var humanDecision = tr.getValue('human_decision');
    var appSysId = tr.application.toString();

    var newStage = 'CLOSED';
    if (humanDecision === 'SELECT') newStage = 'OFFERED';
    if (humanDecision === 'REJECT') newStage = 'REJECTED';
    if (humanDecision === 'HOLD') newStage = 'CLOSED'; // or keep current stage

    // Update Application stage
    var app = new GlideRecord('x_snc_aegis_application');
    if (app.get(appSysId)) {
        app.setValue('stage', newStage);
        app.update();
    }

    // Mark closure complete
    var hdGr = new GlideRecord('x_snc_aegis_hiring_decision');
    if (hdGr.get(tr.sys_id.toString())) {
        hdGr.setValue('closure_complete', true);
        hdGr.setValue('human_decision_at', new GlideDateTime());
        hdGr.update();
    }

    // Log
    var isOverride = tr.getValue('is_override') == '1' || tr.getValue('is_override') === true;
    var logger = new x_snc_aegis.AEGISDecisionLogger();
    logger.logAction(
        'Workflow',
        'STAGE_TRANSITION',
        appSysId,
        tr.requisition.toString(),
        'Human decision: ' + humanDecision + ' | AI recommended: ' + tr.getValue('ai_recommendation') +
            ' | Override: ' + (isOverride ? 'YES — Reason: ' + (tr.getValue('override_reason') || 'N/A') : 'NO'),
        'Application moved to: ' + newStage + ' | Closure complete.',
        null,
        'Human-in-the-loop final gate; Override reason enforced by BR-4'
    );

    outputs.final_stage = newStage;

})(inputs, outputs);

